mapper.select:
select r.cust_id, r.rev_no, f.item_id, f.bucket_type, f.bucket_start, f.qty, f.firm_yn
  from sal_forecast_rev r
  join sal_forecast_line f on f.rev_id = r.rev_id
 where r.rev_no = (select max(x.rev_no) from sal_forecast_rev x where x.cust_id = r.cust_id)
   and f.item_id in #{id}
   and f.bucket_start <= #{to}
   and (case f.bucket_type when 'DAY' then f.bucket_start + 1
                           when 'WEEK' then f.bucket_start + 7
                           else (f.bucket_start + interval '1 month')::date end) > #{from}
 order by f.item_id, r.cust_id, f.bucket_start, f.bucket_type
